def inline(s):
 out=[]; pos=0
 while pos<len(s):
  if s[pos]=='\\' and pos+1<len(s):
   out.append(html.escape(s[pos+1])); pos+=2
  elif s.startswith('**',pos):
   end=pos+2
   while end<len(s):
    if s[end]=='\\': end+=2
    elif s.startswith('**',end): break
    else: end+=1
   assert end<len(s)
   out.append('<strong>'+inline(s[pos+2:end])+'</strong>'); pos=end+2
  elif s[pos]==chr(96):
   end=s.find(chr(96),pos+1)
   assert end!=-1
   out.append('<code>'+html.escape(s[pos+1:end])+'</code>'); pos=end+1
  else:
   out.append(html.escape(s[pos])); pos+=1
 return ''.join(out)
def render(s):
 lines=s.splitlines(); out=[]; pos=0
 while pos<len(lines):
  line=lines[pos]
  if not line:
   pos+=1; continue
  m=re.fullmatch(r'(\x60{3,})text',line)
  if m:
   fence=m[1]; end=pos+1
   while end<len(lines) and lines[end]!=fence: end+=1
   assert end<len(lines)
   out.append('<pre><code class="language-text">'+html.escape('\n'.join(lines[pos+1:end]))+'\n</code></pre>');pos=end+1
  elif line.startswith('- '):
   items=[]
   while pos<len(lines) and lines[pos].startswith('- '):
    items.append('<li>'+inline(lines[pos][2:])+'</li>');pos+=1
   out.append('<ul>'+'\n'.join(items)+'</ul>')
  else:
   para=[]
   while pos<len(lines) and lines[pos]:
    para.append(lines[pos]);pos+=1
   out.append('<p>'+inline('\n'.join(para))+'</p>')
 return '\n'.join(out)
